# Teach Adapt.jl to recurse through our structs, so that `adapt(CuArray, rbm)`,
# `cu(rbm)`, `adapt(Array, rbm)`, and other array backends work out of the box.
# The methods for the layers are generated by `@declare_layer`.
Adapt.adapt_structure(to, rbm::RBM) =
    RBM(Adapt.adapt(to, rbm.visible), Adapt.adapt(to, rbm.hidden), Adapt.adapt(to, rbm.w))
Adapt.adapt_structure(to, rbm::StandardizedRBM) = StandardizedRBM(
    Adapt.adapt(to, rbm.visible), Adapt.adapt(to, rbm.hidden), Adapt.adapt(to, rbm.w),
    Adapt.adapt(to, rbm.offset_v), Adapt.adapt(to, rbm.offset_h),
    Adapt.adapt(to, rbm.scale_v), Adapt.adapt(to, rbm.scale_h)
)
# keep the lazy unit scales of a `CenteredRBM`, which some adaptors (e.g. `adapt(Array, _)`)
# would materialize, turning it into a general `StandardizedRBM`
Adapt.adapt_structure(to, rbm::CenteredRBM) =
    CenteredRBM(Adapt.adapt(to, RBM(rbm)), Adapt.adapt(to, rbm.offset_v), Adapt.adapt(to, rbm.offset_h))
Adapt.adapt_structure(to, ∂::∂RBM) =
    ∂RBM(Adapt.adapt(to, ∂.visible), Adapt.adapt(to, ∂.hidden), Adapt.adapt(to, ∂.w))
